'use client';
import Link from 'next/link';
import { useEffect, useState } from 'react';
import { ApiError, api, uploadFile } from '@/lib/api';
import { ErrorBox, Loading, useApp, useAsync } from '@/components/app/AppShell';
import { useI18n } from '@/components/Providers';
import { ImageCrop } from '@/components/ImageCrop';

interface Item { title?: string; text?: string; photoUrl?: string }
interface Section { type: string; enabled: boolean; content: { title?: string; text?: string; items?: Item[] } }
interface Hours { weekly: { day: number; closed?: boolean; open?: string; close?: string }[]; holidays: { date: string; label?: string }[] }
interface Seo { title?: string; description?: string; ogImage?: string | null; keywords?: string; noindex?: boolean }
interface Theme { font?: string; layout?: string; header?: string; footer?: string }
interface PageDoc { slug: string; title: string; enabled: boolean; seo: { title?: string; description?: string; noindex?: boolean }; sections: Section[] }
interface SiteDoc { templateKey: string; draft: { brand: Record<string, any>; sections: Section[]; seo?: Seo; hours?: Hours; theme?: Theme; pages?: PageDoc[] }; publishedAt: string | null }
const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/; const RESERVED = ['portal', 'properties', 'doctors', 'api', 'app', 'admin', 'login', 'register', 'pricing', 'contact', 'recover', 'products', 'sites', 'driver', 'p', 'sitemap', 'robots'];
const slugify = (v: string) => v.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
const TEMPLATES = [['classic', false], ['modern', false], ['premium-clinic', true], ['premium-store', true]] as const;
const ITEM_TYPES: Record<string, { ar: string; en: string; photo: boolean; text: boolean }> = { about: { ar: 'نقاط القوة', en: 'Highlights', photo: false, text: false }, services: { ar: 'الخدمات', en: 'Services', photo: false, text: true }, team: { ar: 'أعضاء الفريق (الاسم / الوظيفة / الصورة)', en: 'Team members (name / role / photo)', photo: true, text: true }, gallery: { ar: 'صور المعرض', en: 'Gallery images', photo: true, text: false }, faq: { ar: 'الأسئلة الشائعة', en: 'FAQ', photo: false, text: true }, testimonials: { ar: 'آراء العملاء', en: 'Testimonials', photo: false, text: true }, pricing: { ar: 'الباقات والأسعار', en: 'Pricing', photo: false, text: true }, products: { ar: 'المنتجات', en: 'Products', photo: false, text: true } };
const SOCIALS = ['facebook', 'instagram', 'x', 'youtube', 'linkedin', 'tiktok', 'whatsapp'];
const DAY_NAMES = { ar: ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'], en: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'] };
const TYPES = ['hero', 'about', 'services', 'team', 'gallery', 'testimonials', 'contact', 'faq', 'pricing', 'products', 'map', 'hours', 'booking'];
export default function SiteEditor() {
  const app = useApp(); const { t, locale } = useI18n(); const res = useAsync(() => api<SiteDoc>('/tenant/site'), []);
  const [tpl, setTpl] = useState('classic'); const [brand, setBrand] = useState<Record<string, any>>({}); const [secs, setSecs] = useState<Section[]>([]); const [seo, setSeo] = useState<Seo>({}); const [hours, setHours] = useState<Hours>({ weekly: [], holidays: [] }); const [theme, setTheme] = useState<Theme>({}); const [busy, setBusy] = useState(false); const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pages, setPages] = useState<PageDoc[]>([]); const [crop, setCrop] = useState<{ file: File; aspect: number; done: (f: File) => void } | null>(null); const [dragFrom, setDragFrom] = useState<number | null>(null); const [overIdx, setOverIdx] = useState<number | null>(null);
  useEffect(() => { if (res.data) { setTpl(res.data.data.templateKey); setBrand(res.data.data.draft.brand); setSecs(res.data.data.draft.sections); setSeo(res.data.data.draft.seo ?? {}); setHours(res.data.data.draft.hours ?? { weekly: [], holidays: [] }); setTheme(res.data.data.draft.theme ?? {}); setPages(res.data.data.draft.pages ?? []); } }, [res.data]);
  if (res.error) return <ErrorBox error={res.error} retry={res.reload} />; if (!res.data) return <Loading />;
  const setB = (k: string, v: string) => setBrand((b) => ({ ...b, [k]: v === '' ? undefined : v }));
  const body = () => ({ templateKey: tpl, brand: { ...brand, socials: brand.socials ?? {}, description: brand.description ?? '' }, sections: secs, seo: { ...seo, ogImage: seo.ogImage || null }, hours, theme, pages });
  const t2 = (ar: string, en: string) => (locale === 'ar' ? ar : en);
  const patchSec = (i: number, f: (s: Section) => Section) => setSecs((all) => all.map((x, j) => (j === i ? f(x) : x)));
  const setItems = (i: number, items: Item[]) => patchSec(i, (x) => ({ ...x, content: { ...x.content, items } }));
  const dayRow = (d: number) => hours.weekly.find((w) => w.day === d) ?? { day: d, closed: true, open: '09:00', close: '17:00' };
  const setDay = (d: number, patch: Partial<Hours['weekly'][number]>) => setHours((h) => ({ ...h, weekly: [...h.weekly.filter((w) => w.day !== d), { ...dayRow(d), ...patch }].sort((a, b) => a.day - b.day) }));
  const pageErrors = pages.map((p, i) => !SLUG_RE.test(p.slug) ? t2('العنوان: حروف إنجليزية صغيرة وأرقام وشرطات فقط', 'Address: lowercase letters, digits and hyphens only') : p.slug.length < 2 ? t2('العنوان قصير جدًا', 'Address is too short') : RESERVED.includes(p.slug) ? t2('هذا العنوان محجوز', 'This address is reserved') : pages.findIndex((q) => q.slug === p.slug) !== i ? t2('العنوان مكرر — لكل صفحة عنوان مختلف', 'Duplicate address — every page needs its own') : '');
  const patchPage = (i: number, f: (p: PageDoc) => PageDoc) => setPages((all) => all.map((x, j) => (j === i ? f(x) : x)));
  /** Opens the crop dialog for a chosen image; the CROPPED file (not the original) is what gets uploaded. GIFs are uploaded as-is (cropping would flatten the animation). */
  const withCrop = (f: File | undefined, aspect: number, done: (f: File) => void) => { if (!f) return; if (f.type === 'image/gif') return done(f); setCrop({ file: f, aspect, done }); };
  const dropAt = (to: number) => { if (dragFrom === null || dragFrom === to) return; setSecs((s) => { const n = [...s]; const [m] = n.splice(dragFrom, 1); n.splice(to, 0, m); return n; }); setDragFrom(null); setOverIdx(null); };
  async function upload(file: File | undefined, done: (url: string) => void) { if (!file) return; setMsg(null); setBusy(true); try { const r = await uploadFile('site', file); done(r.url); } catch (e) { setMsg({ ok: false, text: (e as ApiError).message }); } finally { setBusy(false); } }
  async function save() { setMsg(null); const bad = pageErrors.find(Boolean); if (bad) return setMsg({ ok: false, text: bad }); try { await api('/tenant/site', { method: 'PUT', body: body() }); setMsg({ ok: true, text: t('saved') }); res.reload(); } catch (e) { const a = e as ApiError; setMsg({ ok: false, text: a.message + (a.fields ? ' — ' + Object.entries(a.fields).map(([k, v]) => `${k}: ${v.join(', ')}`).join('; ') : '') }); } }
  async function publish() { setMsg(null); const bad = pageErrors.find(Boolean); if (bad) return setMsg({ ok: false, text: bad }); try { await api('/tenant/site', { method: 'PUT', body: body() }); await api('/tenant/site/publish', { method: 'POST', body: {} }); setMsg({ ok: true, text: t('published') }); res.reload(); } catch (e) { setMsg({ ok: false, text: (e as ApiError).message }); } }
  const move = (i: number, d: number) => setSecs((s) => { const n = [...s]; const j = i + d; if (j < 0 || j >= n.length) return s; [n[i], n[j]] = [n[j], n[i]]; return n; });
  return (
    <>
      <div className="row between"><h1 style={{ fontSize: '1.6rem', margin: 0 }}>{t('website')}</h1><div className="row">
        <span className={`badge ${res.data.data.publishedAt ? 'ok' : 'warn'}`}>{res.data.data.publishedAt ? t('published') : t('draft')}</span>
        <Link className="btn" target="_blank" href={`/sites/${app.me.tenant.slug}`}>{t('preview')}</Link><button className="btn" onClick={save}>{t('save')}</button><button className="btn primary" onClick={publish}>{t('publish')}</button></div></div>
      {msg && <div className={`alert ${msg.ok ? 'ok' : 'error'}`} role="alert">{msg.text}</div>}
      <section className="card stack"><h3>{t('brand')}</h3>
        <div className="grid g2">
          <label className="field">{t('businessName')}<input value={brand.name ?? ''} onChange={(e) => setB('name', e.target.value)} /></label>
          <label className="field">{t('template')}<select value={tpl} onChange={(e) => setTpl(e.target.value)}>{TEMPLATES.map(([k, premium]) => <option key={k} value={k}>{k}{premium ? ' ★' : ''}</option>)}</select><span className="hint">★ {locale === 'ar' ? 'يحتاج إضافة القوالب المميزة' : 'requires the Premium templates add-on'}</span></label>
          <label className="field">{t('primaryColor')}<input type="color" value={brand.primaryColor ?? '#000000'} onChange={(e) => setB('primaryColor', e.target.value)} /></label>
          <label className="field">{t('secondaryColor')}<input type="color" value={brand.secondaryColor ?? '#000000'} onChange={(e) => setB('secondaryColor', e.target.value)} /></label>
          <label className="field">{t('logoUrl')}<input className="ltr" value={brand.logoUrl ?? ''} onChange={(e) => setB('logoUrl', e.target.value)} /></label>
          <label className="field">{locale === 'ar' ? 'رفع شعار (PNG / JPG / WebP حتى 2 ميجا)' : 'Upload logo (PNG / JPG / WebP, up to 2 MB)'}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={async (e) => { const f = e.target.files?.[0]; e.target.value = ''; withCrop(f, 1, async (c) => { setMsg(null); try { const r = await uploadFile('logo', c); setB('logoUrl', r.url); setMsg({ ok: true, text: locale === 'ar' ? 'تم رفع الشعار، اضغط حفظ.' : 'Logo uploaded — press Save.' }); } catch (x) { setMsg({ ok: false, text: (x as ApiError).message }); } }); }} /></label>
          <label className="field">{t('phone')}<input className="ltr" value={brand.phone ?? ''} onChange={(e) => setB('phone', e.target.value)} /></label>
          <label className="field">{t('email')}<input className="ltr" value={brand.email ?? ''} onChange={(e) => setB('email', e.target.value)} /></label>
          <label className="field">{t('address')}<input value={brand.address ?? ''} onChange={(e) => setB('address', e.target.value)} /></label></div>
        <label className="field">{t('description')}<textarea value={brand.description ?? ''} onChange={(e) => setB('description', e.target.value)} /></label></section>
      <section className="card stack"><h3>{t2('وسائل التواصل الاجتماعي', 'Social links')}</h3>
        <div className="grid g2">{SOCIALS.map((k) => <label key={k} className="field">{k}<input className="ltr" inputMode="url" placeholder="https://" value={(brand.socials ?? {})[k] ?? ''} onChange={(e) => setBrand((b) => { const so = { ...(b.socials ?? {}) }; if (e.target.value) so[k] = e.target.value; else delete so[k]; return { ...b, socials: so }; })} /></label>)}</div></section>
      <section className="card stack"><h3>{t('sections')}</h3><p className="hint">{t2('اكتب هنا من أنتم وماذا تقدّمون. كل ما تكتبه يظهر في موقعك العام بعد الضغط على نشر.', 'Describe who you are and what you offer. Everything you write appears on your public site after you publish.')}</p>
        {secs.map((s, i) => { const it = ITEM_TYPES[s.type]; const items = s.content.items ?? []; return (
          <div key={i} data-testid="section-card" data-type={s.type} className="card flat stack" onDragOver={(e) => { if (dragFrom !== null) { e.preventDefault(); setOverIdx(i); } }} onDrop={(e) => { e.preventDefault(); dropAt(i); }} style={overIdx === i && dragFrom !== null && dragFrom !== i ? { outline: '2px dashed var(--color-primary)' } : undefined}><div className="row between"><label className="row"><span draggable data-testid="drag-handle" role="img" aria-label={t2('اسحب لإعادة الترتيب', 'Drag to reorder')} title={t2('اسحب لإعادة الترتيب', 'Drag to reorder')} onDragStart={(e) => { setDragFrom(i); e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', String(i)); }} onDragEnd={() => { setDragFrom(null); setOverIdx(null); }} style={{ cursor: 'grab', display: 'inline-block', minWidth: 28, minHeight: 28, lineHeight: '28px', textAlign: 'center', userSelect: 'none', border: '1px dashed var(--border)', borderRadius: 6 }}>⠿</span><input type="checkbox" checked={s.enabled} onChange={(e) => patchSec(i, (x) => ({ ...x, enabled: e.target.checked }))} /><b>{s.type}</b></label>
            <div className="row"><button className="btn sm" onClick={() => move(i, -1)} aria-label={t2('تحريك لأعلى', 'Move up')}>↑</button><button className="btn sm" onClick={() => move(i, 1)} aria-label={t2('تحريك لأسفل', 'Move down')}>↓</button><button className="btn sm danger" onClick={() => setSecs(secs.filter((_, j) => j !== i))}>{t('remove')}</button></div></div>
            {s.type !== 'hours' && s.type !== 'contact' && <div className="grid g2"><label className="field">{t('title')}<input maxLength={200} value={s.content.title ?? ''} onChange={(e) => patchSec(i, (x) => ({ ...x, content: { ...x.content, title: e.target.value } }))} /></label>
              <label className="field">{t('message')}<textarea rows={3} maxLength={3000} value={s.content.text ?? ''} onChange={(e) => patchSec(i, (x) => ({ ...x, content: { ...x.content, text: e.target.value } }))} /></label></div>}
            {s.type === 'hours' && <p className="hint">{t2('تُعرض ساعات العمل والإجازات المعرّفة أدناه.', 'Shows the working hours and holidays defined below.')}</p>}
            {it && <div className="stack"><b className="small">{locale === 'ar' ? it.ar : it.en}</b>
              {items.map((x, k) => <div key={k} className="card flat stack" style={{ padding: 10 }}><div className="grid g2">
                <label className="field">{s.type === 'team' ? t2('الاسم', 'Name') : t('title')}<input maxLength={200} value={x.title ?? ''} onChange={(e) => setItems(i, items.map((y, n) => (n === k ? { ...y, title: e.target.value } : y)))} /></label>
                {it.text && <label className="field">{s.type === 'team' ? t2('الوظيفة', 'Job title') : t('message')}<input maxLength={1500} value={x.text ?? ''} onChange={(e) => setItems(i, items.map((y, n) => (n === k ? { ...y, text: e.target.value } : y)))} /></label>}
                {it.photo && <label className="field">{t2('صورة (PNG / JPG / WebP حتى 5 ميجا)', 'Photo (PNG / JPG / WebP, up to 5 MB)')}<input type="file" accept="image/png,image/jpeg,image/webp" disabled={busy} onChange={(e) => { const f = e.target.files?.[0]; e.target.value = ''; withCrop(f, s.type === 'team' ? 1 : 4 / 3, (c) => upload(c, (url) => setItems(i, items.map((y, n) => (n === k ? { ...y, photoUrl: url } : y))))); }} /></label>}</div>
                {x.photoUrl && <div className="row"><img src={x.photoUrl} alt={x.title ?? ''} style={{ width: 64, height: 64, objectFit: 'cover', borderRadius: 8 }} /><button className="btn sm" onClick={() => setItems(i, items.map((y, n) => (n === k ? { ...y, photoUrl: undefined } : y)))}>{t2('إزالة الصورة', 'Remove photo')}</button></div>}
                <div><button className="btn sm danger" onClick={() => setItems(i, items.filter((_, n) => n !== k))}>{t('remove')}</button></div></div>)}
              <div><button className="btn sm" disabled={items.length >= 40} onClick={() => setItems(i, [...items, { title: '' }])}>+ {t2('إضافة عنصر', 'Add item')}</button></div></div>}</div>); })}
        <select aria-label={t('create')} value="" onChange={(e) => e.target.value && setSecs([...secs, { type: e.target.value, enabled: true, content: {} }])} style={{ width: 'auto' }}><option value="">+ {t('sections')}</option>{TYPES.map((x) => <option key={x} value={x}>{x}</option>)}</select></section>
      <section className="card stack" data-testid="pages-manager"><h3>{t2('صفحات إضافية (روابط SEO)', 'Extra pages (SEO addresses)')}</h3>
        <p className="hint">{t2('كل صفحة لها عنوان مستقل يظهر في الرابط وفي محركات البحث، وتظهر في قائمة الموقع بعد النشر.', 'Each page gets its own address in the URL and its own search-engine title; it shows in the site menu after you publish.')}</p>
        {pages.map((p, i) => <div key={i} className="card flat stack" data-testid="page-card"><div className="grid g2">
          <label className="field">{t2('عنوان الصفحة', 'Page title')}<input maxLength={120} value={p.title} onChange={(e) => patchPage(i, (x) => ({ ...x, title: e.target.value, slug: x.slug === '' || x.slug === slugify(x.title) ? slugify(e.target.value) : x.slug }))} /></label>
          <label className="field">{t2('عنوان الرابط (slug)', 'URL slug')}<input className="ltr" maxLength={60} aria-invalid={!!pageErrors[i]} aria-describedby={`slug-err-${i}`} value={p.slug} onChange={(e) => patchPage(i, (x) => ({ ...x, slug: e.target.value.toLowerCase() }))} /><span className="hint mono">/sites/{app.me.tenant.slug}/{p.slug || '…'}</span>{pageErrors[i] && <span id={`slug-err-${i}`} className="hint" role="alert" style={{ color: 'var(--danger)' }}>{pageErrors[i]}</span>}</label>
          <label className="field">{t2('عنوان SEO', 'SEO title')}<input maxLength={70} value={p.seo.title ?? ''} onChange={(e) => patchPage(i, (x) => ({ ...x, seo: { ...x.seo, title: e.target.value } }))} /></label>
          <label className="field">{t2('وصف SEO', 'SEO description')}<input maxLength={200} value={p.seo.description ?? ''} onChange={(e) => patchPage(i, (x) => ({ ...x, seo: { ...x.seo, description: e.target.value } }))} /></label></div>
          <label className="row"><input type="checkbox" checked={p.enabled} onChange={(e) => patchPage(i, (x) => ({ ...x, enabled: e.target.checked }))} />{t2('منشورة', 'Enabled')}</label>
          {p.sections.map((sec, k) => <div key={k} className="card flat stack" style={{ padding: 10 }}><div className="row between"><b className="small">{sec.type}</b><button className="btn sm danger" onClick={() => patchPage(i, (x) => ({ ...x, sections: x.sections.filter((_, n) => n !== k) }))}>{t('remove')}</button></div>
            <div className="grid g2"><label className="field">{t('title')}<input maxLength={200} value={sec.content.title ?? ''} onChange={(e) => patchPage(i, (x) => ({ ...x, sections: x.sections.map((y, n) => (n === k ? { ...y, content: { ...y.content, title: e.target.value } } : y)) }))} /></label>
              <label className="field">{t('message')}<textarea rows={2} maxLength={3000} value={sec.content.text ?? ''} onChange={(e) => patchPage(i, (x) => ({ ...x, sections: x.sections.map((y, n) => (n === k ? { ...y, content: { ...y.content, text: e.target.value } } : y)) }))} /></label></div></div>)}
          <div className="row"><select aria-label={t2('إضافة قسم للصفحة', 'Add a section to this page')} value="" onChange={(e) => e.target.value && patchPage(i, (x) => ({ ...x, sections: [...x.sections, { type: e.target.value, enabled: true, content: {} }] }))} style={{ width: 'auto' }}><option value="">+ {t('sections')}</option>{TYPES.filter((x) => x !== 'hero').map((x) => <option key={x} value={x}>{x}</option>)}</select>
            <button className="btn sm danger" onClick={() => setPages(pages.filter((_, n) => n !== i))}>{t2('حذف الصفحة', 'Delete page')}</button></div></div>)}
        <div><button className="btn sm" disabled={pages.length >= 12} onClick={() => setPages([...pages, { slug: '', title: '', enabled: true, seo: {}, sections: [{ type: 'about', enabled: true, content: {} }] }])}>+ {t2('إضافة صفحة', 'Add page')}</button></div></section>
      <section className="card stack"><h3>{t2('ساعات العمل والإجازات', 'Working hours & holidays')}</h3>
        <div className="table-wrap"><table><thead><tr><th scope="col">{t2('اليوم', 'Day')}</th><th scope="col">{t2('مغلق', 'Closed')}</th><th scope="col">{t2('من', 'From')}</th><th scope="col">{t2('إلى', 'To')}</th></tr></thead>
          <tbody>{[6, 0, 1, 2, 3, 4, 5].map((d) => { const r = dayRow(d); return <tr key={d}><th scope="row">{DAY_NAMES[locale === 'ar' ? 'ar' : 'en'][d]}</th><td><input type="checkbox" aria-label={t2('مغلق', 'Closed') + ' ' + DAY_NAMES[locale === 'ar' ? 'ar' : 'en'][d]} checked={!!r.closed} onChange={(e) => setDay(d, { closed: e.target.checked })} /></td>
            <td><input type="time" aria-label={t2('من', 'From')} disabled={!!r.closed} value={r.open ?? '09:00'} onChange={(e) => setDay(d, { open: e.target.value })} /></td><td><input type="time" aria-label={t2('إلى', 'To')} disabled={!!r.closed} value={r.close ?? '17:00'} onChange={(e) => setDay(d, { close: e.target.value })} /></td></tr>; })}</tbody></table></div>
        <b className="small">{t2('الإجازات', 'Holidays')}</b>
        {hours.holidays.map((h, k) => <div key={k} className="row"><input type="date" aria-label={t2('التاريخ', 'Date')} value={h.date} onChange={(e) => setHours((x) => ({ ...x, holidays: x.holidays.map((y, n) => (n === k ? { ...y, date: e.target.value } : y)) }))} /><input aria-label={t2('المناسبة', 'Occasion')} maxLength={80} value={h.label ?? ''} onChange={(e) => setHours((x) => ({ ...x, holidays: x.holidays.map((y, n) => (n === k ? { ...y, label: e.target.value } : y)) }))} /><button className="btn sm danger" onClick={() => setHours((x) => ({ ...x, holidays: x.holidays.filter((_, n) => n !== k) }))}>{t('remove')}</button></div>)}
        <div><button className="btn sm" disabled={hours.holidays.length >= 40} onClick={() => setHours((x) => ({ ...x, holidays: [...x.holidays, { date: new Date().toISOString().slice(0, 10), label: '' }] }))}>+ {t2('إضافة إجازة', 'Add holiday')}</button></div></section>
      <section className="card stack"><h3>{t2('المظهر', 'Appearance')}</h3>
        <div className="grid g2">{([['font', t2('الخط', 'Typography'), ['default', 'serif', 'rounded', 'mono']], ['layout', t2('التخطيط', 'Layout'), ['standard', 'wide', 'compact']], ['header', t2('الهيدر', 'Header'), ['solid', 'transparent', 'centered']], ['footer', t2('الفوتر', 'Footer'), ['simple', 'columns']]] as const).map(([k, label, opts]) =>
          <label key={k} className="field">{label}<select value={theme[k] ?? opts[0]} onChange={(e) => setTheme((x) => ({ ...x, [k]: e.target.value }))}>{opts.map((o) => <option key={o} value={o}>{o}</option>)}</select></label>)}</div></section>
      <section className="card stack"><h3>{t2('تحسين محركات البحث (SEO)', 'SEO')}</h3>
        <label className="field">{t2('عنوان الصفحة (حتى 70 حرفًا)', 'Page title (up to 70 characters)')}<input maxLength={70} value={seo.title ?? ''} onChange={(e) => setSeo({ ...seo, title: e.target.value })} /></label>
        <label className="field">{t2('وصف الصفحة meta (حتى 200 حرف)', 'Meta description (up to 200 characters)')}<textarea rows={2} maxLength={200} value={seo.description ?? ''} onChange={(e) => setSeo({ ...seo, description: e.target.value })} /><span className="hint">{(seo.description ?? '').length}/200</span></label>
        <label className="field">{t2('كلمات مفتاحية', 'Keywords')}<input maxLength={200} value={seo.keywords ?? ''} onChange={(e) => setSeo({ ...seo, keywords: e.target.value })} /></label>
        <label className="field">{t2('صورة المشاركة (Open Graph)', 'Share image (Open Graph)')}<input type="file" accept="image/png,image/jpeg,image/webp" disabled={busy} onChange={(e) => { const f = e.target.files?.[0]; e.target.value = ''; withCrop(f, 1.91, (c) => upload(c, (url) => setSeo((x) => ({ ...x, ogImage: url })))); }} /></label>
        {seo.ogImage && <div className="row"><img src={seo.ogImage} alt={t2('صورة المشاركة', 'Share image')} style={{ width: 120, borderRadius: 8 }} /><button className="btn sm" onClick={() => setSeo((x) => ({ ...x, ogImage: null }))}>{t2('إزالة', 'Remove')}</button></div>}
        <label className="row"><input type="checkbox" checked={!!seo.noindex} onChange={(e) => setSeo({ ...seo, noindex: e.target.checked })} />{t2('إخفاء الموقع عن محركات البحث', 'Hide this site from search engines')}</label>
        <span className="hint">{t2('عنوان موقعك: ', 'Your site address: ')}<span className="mono">/sites/{app.me.tenant.slug}</span></span></section>
    {crop && <ImageCrop file={crop.file} aspect={crop.aspect} locale={locale === 'ar' ? 'ar' : 'en'} onCancel={() => setCrop(null)} onDone={(f) => { const d = crop.done; setCrop(null); d(f); }} />}
    </>
  );
}
